type Json = Record<string, any>;

class ApiError extends Error {
  status: number;
  body: any;
  method: string;
  path: string;

  constructor(method: string, path: string, status: number, body: any) {
    super(`${method} ${path} failed with ${status}`);
    this.status = status;
    this.body = body;
    this.method = method;
    this.path = path;
  }
