      } else {
        url.searchParams.set(key, String(raw));
      }
    }
  }
  return url;
}

async function api<T = any>(method: string, path: string, opts: { query?: Record<string, any>; body?: any } = {}): Promise<T> {
  const url = buildUrl(path, opts.query);
  const response = await fetch(url, {
    method,
    headers: {
